<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=mysqli_query($conn,"SELECT e.id,e.name employee_name,m.name manager_name FROM employees e LEFT JOIN employees m ON e.manager_id=m.id ORDER BY e.id"); ?>
